        rows.append({"name": f"test_repro_{i}", "call": case["call"],
                     "outcome": "passed" if kind == "passed" else "failure", "kind": kind,
                     "message": message, "where": result.get("where", ""), "both": False})
    bad = [r for r in rows if r["outcome"] == "failure"]
